var imageDigestPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9._/:-]{0,200}@sha256:[0-9a-f]{64}$`)
var envNamePattern = regexp.MustCompile(`^[A-Z][A-Z0-9_]{0,63}$`)

// ReservedEnv are the names the platform sets itself; a manifest cannot override them.
func ReservedEnv(name string) bool {
	return strings.HasPrefix(name, "K3_") || name == "PORT" || name == "PATH" || name == "HOME"
}

// Defaults returns the runtime with the platform's defaults filled in.
func (r Runtime) Defaults() Runtime {
	if r.Port == 0 {
		r.Port = DefaultRuntimePort
	}
	if r.MemoryMB == 0 {
		r.MemoryMB = 256
	}
	if r.CPUMilli == 0 {
		r.CPUMilli = 250
	}
	if r.Health == "" {
		r.Health = "/"
	}
	if r.Isolation == "" {
		r.Isolation = "shared"
	}
	return r
}

func (r Runtime) validate(add func(string, ...any)) {
	if !imageDigestPattern.MatchString(r.Image) {
		add("runtime.image must be pinned by digest: name@sha256:<64 hex characters>")
	}
	if r.Port < 0 || r.Port > 65535 || (r.Port != 0 && r.Port < 1024) {
		add("runtime.port must be 1024..65535")
	}
	if r.MemoryMB < 0 || r.MemoryMB > MaxRuntimeMemoryMB {
		add("runtime.memoryMb must be at most %d", MaxRuntimeMemoryMB)
	}
	if r.CPUMilli < 0 || r.CPUMilli > MaxRuntimeCPUMilli {
		add("runtime.cpuMilli must be at most %d", MaxRuntimeCPUMilli)
	}
	if r.Health != "" && !strings.HasPrefix(r.Health, "/") {
		add("runtime.health must be a path starting with /")
	}
	if r.HealthIntervalSec != 0 && (r.HealthIntervalSec < MinHealthIntervalSec || r.HealthIntervalSec > MaxHealthIntervalSec) {
		add("runtime.healthIntervalSec must be %d..%d", MinHealthIntervalSec, MaxHealthIntervalSec)
	}
	if r.HealthFailures < 0 || r.HealthFailures > MaxHealthFailures {
		add("runtime.healthFailures must be 1..%d", MaxHealthFailures)
	}
	if (r.HealthIntervalSec != 0 || r.HealthFailures != 0) && r.Health == "" {
		add("runtime.healthIntervalSec and runtime.healthFailures need runtime.health (the path to probe)")
	}
	if len(r.Command) > 16 {
		add("runtime.command has too many parts")
	}
	if len(r.Env) > 32 {
		add("runtime.env has too many entries")
	}
	for k, v := range r.Env {
		if !envNamePattern.MatchString(k) || ReservedEnv(k) {
			add("runtime.env: %q is not a usable name (upper case, not K3_*, PORT, PATH or HOME)", k)
		}
		if len(v) > 1024 {
			add("runtime.env: the value of %s is too long", k)
		}
	}
	if r.Isolation != "" && r.Isolation != "shared" {
		add("runtime.isolation: only shared is available")
	}
}

